17	/**
18	 * 预降业务门面：编排事务边界、requestId 幂等与各业务服务。
19	 *
20	 * <p>幂等接口（预警、启停、归档）的占位抢占、业务写库与首次结果回写处于同一事务：
21	 * 业务失败整体回滚；同键异参抛 409 且无任何写入。液位接口不走 requestId，
22	 * 但“数据入库＋自动停泵＋失联派单”在同一事务内原子提交。
23	 */
24	@Service
25	public class PumpdownFacade {
26	
27	    private final IdempotencyTemplate idempotency;
28	    private final WarningService warningService;
29	    private final PumpCommandService pumpCommandService;
30	    private final LevelService levelService;
31	    private final ArchiveService archiveService;
32	    private final ReplayService replayService;
33	
34	    public PumpdownFacade(IdempotencyTemplate idempotency,
35	                          WarningService warningService,
36	                          PumpCommandService pumpCommandService,
37	                          LevelService levelService,
38	                          ArchiveService archiveService,
39	                          ReplayService replayService) {
40	        this.idempotency = idempotency;
41	        this.warningService = warningService;
42	        this.pumpCommandService = pumpCommandService;
43	        this.levelService = levelService;
44	        this.archiveService = archiveService;
45	        this.replayService = replayService;
46	    }
47	
48	    /** 气象预警：橙色及以上启动预降。 */
49	    @Transactional
50	    public WarningResult handleWarning(WarningRequest request) {
51	        String fingerprint = Fingerprints.sha256(request.requestId(), request.zoneCode(),
52	                request.alertLevel(), request.alertTime());
53	        IdempotencyTemplate.Outcome<WarningResult> outcome = idempotency.execute(
54	                request.requestId(), "WARNING", fingerprint,
55	                HttpStatus.ACCEPTED.value(),
56	                () -> warningService.process(request),
57	                WarningResult.class);
58	        return withReplayed(outcome.value(), outcome.replayed());
59	    }
60	
61	    /** 泵站启停。 */
62	    @Transactional
63	    public PumpCommandResult handlePumpCommand(PumpCommandRequest request) {
64	        String fingerprint = Fingerprints.sha256(request.requestId(), request.pumpdownId(),
65	                request.stationCode(), request.action(), request.taskTime(),
66	                request.gateOpening());
67	        IdempotencyTemplate.Outcome<PumpCommandResult> outcome = idempotency.execute(
68	                request.requestId(), "PUMP_TASK", fingerprint,
69	                HttpStatus.ACCEPTED.value(),
70	                () -> pumpCommandService.processManual(request),
71	                PumpCommandResult.class);
72	        PumpCommandResult value = outcome.value();
73	        if (outcome.replayed()) {
74	            return new PumpCommandResult(value.taskId(), value.sequenceId(), value.pumpdownId(),
75	                    value.stationCode(), value.action(), value.taskTime(), value.gateOpening(),
76	                    value.reason(), true);
77	        }
78	        return value;
79	    }
80	
81	    /** 液位复测：非 requestId 幂等，但事务内原子处理去重、停泵、派单。 */
82	    @Transactional
83	    public LevelIngestResult handleLevel(LevelIngestRequest request) {
84	        return levelService.ingest(request);
85	    }
86	
87	    /** 复盘归档：终态，重复归档幂等成功。 */
88	    @Transactional
89	    public ArchiveResult handleArchive(ArchiveRequest request) {
90	        String fingerprint = Fingerprints.sha256(request.requestId(), request.pumpdownId(),
91	                request.archiveTime());
92	        IdempotencyTemplate.Outcome<ArchiveResult> outcome = idempotency.execute(
93	                request.requestId(), "ARCHIVE", fingerprint,
94	                HttpStatus.OK.value(),
95	                () -> archiveService.archive(request),
96	                ArchiveResult.class);
97	        ArchiveResult value = outcome.value();
98	        if (outcome.replayed()) {
99	            return new ArchiveResult(value.pumpdownId(), value.status(), value.archivedAt(),
100	                    value.summary(), true);
101	        }
102	        return value;
103	    }
104	
105	    /** 台账复算。 */
106	    @Transactional(readOnly = true)
107	    public ReplayResult replay(Long pumpdownId) {
108	        return replayService.replay(pumpdownId);
109	    }
110	
111	    private WarningResult withReplayed(WarningResult value, boolean replayed) {
112	        if (!replayed) {
113	            return value;
114	        }
115	        return new WarningResult(value.pumpdownId(), value.zoneCode(), value.alertLevel(),
116	                value.triggered(), value.status(), value.startedAt(), value.targetLevel(), true);
117	    }
118	}
