1	package com.example.starter.pump.service;
2	
3	import com.example.starter.pump.domain.PumpStation;
4	import com.example.starter.pump.domain.PumpdownEvent;
5	import com.example.starter.pump.error.ApiException;
6	import com.example.starter.pump.repo.CatalogRepository;
7	import com.example.starter.pump.repo.PumpTaskRepository;
8	import com.example.starter.pump.repo.PumpdownEventRepository;
9	import com.example.starter.pump.web.dto.PumpCommandRequest;
10	import com.example.starter.pump.web.dto.PumpCommandResult;
11	import org.springframework.stereotype.Service;
12	
13	import java.math.BigDecimal;
14	import java.time.Duration;
15	import java.time.LocalDateTime;
16	
17	/**
18	 * 泵站启停：启机间隔不少于10分钟（恰10分钟合法）、分区同时刻唯一序列、
19	 * 同站同时刻唯一任务，启泵与闸门开度同事务提交。
20	 */
21	@Service
22	public class PumpCommandService {
23	
24	    /** 相邻两次启机的最小间隔。 */
25	    static final Duration MIN_START_INTERVAL = Duration.ofMinutes(10);
26	
27	    private final PumpTaskRepository taskRepository;
28	    private final PumpdownEventRepository eventRepository;
29	    private final CatalogRepository catalogRepository;
30	
31	    public PumpCommandService(PumpTaskRepository taskRepository,
32	                              PumpdownEventRepository eventRepository,
33	                              CatalogRepository catalogRepository) {
34	        this.taskRepository = taskRepository;
35	        this.eventRepository = eventRepository;
36	        this.catalogRepository = catalogRepository;
37	    }
38	
39	    /** 处理手动启停指令（幂等首次执行体）。 */
40	    public PumpCommandResult processManual(PumpCommandRequest request) {
41	        PumpdownEvent event = requireActiveEvent(request.pumpdownId());
42	        PumpStation station = requireStationInZone(request.stationCode(), event.zoneCode());
43	        return switch (request.action()) {
44	            case "START" -> start(station, event, request.taskTime(),
45	                    request.gateOpening(), "MANUAL_START");
46	            case "STOP" -> stop(station, event, request.taskTime(), "MANUAL_STOP");
47	            default -> throw ApiException.unprocessable("UNKNOWN_ACTION")
48	                    .raise("未知启停动作: " + request.action() + "（仅支持 START/STOP）");
49	        };
50	    }
51	
52	    /**
53	     * 液位复测触发的自动停泵（恰达目标位或低于安全下限），不走 requestId 幂等。
54	     *
55	     * @return 停泵任务ID；泵本已停止返回 null
56	     */
57	    public Long autoStop(PumpStation station, PumpdownEvent event, LocalDateTime taskTime,
58	                         String reason) {
59	        PumpTaskRepository.LastTask last = taskRepository.latestTask(station.code(), event.id());
60	        if (last == null || !last.running()) {
61	            return null;
62	        }
63	        Long sequenceId = taskRepository.findOrCreateSequence(event.id(), station.zoneCode(),
64	                taskTime, taskTime);
65	        Long taskId = taskRepository.insertTask(sequenceId, event.id(), station.code(), "STOP",
66	                taskTime, reason);
67	        return taskId;
68	    }
69	
70	    private PumpCommandResult start(PumpStation station, PumpdownEvent event,
71	                                    LocalDateTime taskTime, BigDecimal requestedOpening,
72	                                    String reason) {
73	        PumpTaskRepository.LastTask last = taskRepository.latestTask(station.code(), event.id());
74	        if (last != null && last.running()) {
75	            throw ApiException.unprocessable("PUMP_ALREADY_RUNNING")
76	                    .raise("泵站 " + station.code() + " 已在运行，禁止重复启泵");
77	        }
78	        if (last != null) {
79	            LocalDateTime latestStart = taskRepository.latestStartTimeBefore(station.code(), taskTime);
80	            if (latestStart != null
81	                    && Duration.between(latestStart, taskTime).compareTo(MIN_START_INTERVAL) < 0) {
82	                throw ApiException.unprocessable("START_INTERVAL_TOO_SHORT")
83	                        .raise("泵站 " + station.code() + " 距上次启泵不足10分钟，防水锤拒绝启泵");
84	            }
85	        }
86	
87	        BigDecimal opening = requestedOpening != null ? requestedOpening : station.gateStartOpening();
88	        if (opening.compareTo(BigDecimal.ZERO) < 0 || opening.compareTo(BigDecimal.valueOf(100)) > 0) {
89	            throw ApiException.unprocessable("INVALID_GATE_OPENING")
90	                    .raise("闸门开度必须在0-100之间: " + opening);
91	        }
92	
93	        Long sequenceId;
94	        Long taskId;
95	        try {
96	            sequenceId = taskRepository.findOrCreateSequence(event.id(), station.zoneCode(),
97	                    taskTime, taskTime);
98	            taskId = taskRepository.insertTask(sequenceId, event.id(), station.code(), "START",
99	                    taskTime, reason);
100	        } catch (org.springframework.dao.DuplicateKeyException e) {
101	            throw ApiException.concurrentConflict("ZONE_SEQUENCE_CONFLICT",
102	                    "分区 " + station.zoneCode() + " 在 " + taskTime + " 的联动序列正被并发创建，唯一受理");
103	        }
104	        if (taskId == null) {
105	            throw ApiException.concurrentConflict("STATION_TIME_CONFLICT",
106	                    "泵站 " + station.code() + " 在 " + taskTime + " 已存在启停任务，并发指令唯一受理");
107	        }
108	        // 与启泵任务同一事务：闸门未到位则整体回滚，绝不允许开泵而闸门未联动
109	        taskRepository.insertGateLog(taskId, station.code(), opening, taskTime);
110	
111	        return new PumpCommandResult(taskId, sequenceId, event.id(), station.code(), "START",
112	                taskTime, opening, reason, false);
113	    }
114	
115	    private PumpCommandResult stop(PumpStation station, PumpdownEvent event,
116	                                   LocalDateTime taskTime, String reason) {
117	        PumpTaskRepository.LastTask last = taskRepository.latestTask(station.code(), event.id());
118	        if (last == null || !last.running()) {
119	            throw ApiException.unprocessable("PUMP_NOT_RUNNING")
120	                    .raise("泵站 " + station.code() + " 当前未运行，无需停泵");
121	        }
122	        Long sequenceId = taskRepository.findOrCreateSequence(event.id(), station.zoneCode(),
123	                taskTime, taskTime);
124	        Long taskId = taskRepository.insertTask(sequenceId, event.id(), station.code(), "STOP",
125	                taskTime, reason);
126	        if (taskId == null) {
127	            throw ApiException.concurrentConflict("STATION_TIME_CONFLICT",
128	                    "泵站 " + station.code() + " 在 " + taskTime + " 已存在启停任务，并发指令唯一受理");
129	        }
130	        return new PumpCommandResult(taskId, sequenceId, event.id(), station.code(), "STOP",
131	                taskTime, null, reason, false);
132	    }
133	
134	    private PumpdownEvent requireActiveEvent(Long pumpdownId) {
135	        PumpdownEvent event = eventRepository.findById(pumpdownId)
136	                .orElseThrow(() -> ApiException.unprocessable("PUMPDOWN_NOT_FOUND")
137	                        .raise("预降事件不存在: " + pumpdownId));
138	        if (!event.active()) {
139	            throw ApiException.unprocessable("PUMPDOWN_ARCHIVED")
140	                    .raise("预降事件 " + pumpdownId + " 已归档终态，不可再启停");
141	        }
142	        return event;
143	    }
144	
145	    private PumpStation requireStationInZone(String stationCode, String zoneCode) {
146	        PumpStation station = catalogRepository.findStation(stationCode)
147	                .orElseThrow(() -> ApiException.unprocessable("STATION_NOT_FOUND")
148	                        .raise("泵站不存在: " + stationCode));
149	        if (!station.zoneCode().equals(zoneCode)) {
150	            throw ApiException.unprocessable("STATION_ZONE_MISMATCH")
151	                    .raise("泵站 " + stationCode + " 不属于预降分区 " + zoneCode);
152	        }
153	        return station;
154	    }
155	}
