/**
 * 城市内涝泵站联动预降服务 HTTP 入口。
 */
@RestController
@RequestMapping("/api")
public class PumpController {

    private final PumpdownFacade facade;

    public PumpController(PumpdownFacade facade) {
        this.facade = facade;
    }

    /** 气象预警上送：橙色及以上启动预降。 */
    @PostMapping("/warnings")
