3	import com.example.starter.pump.web.dto.ReplayResult;
4	import org.springframework.dao.DuplicateKeyException;
5	import org.springframework.dao.EmptyResultDataAccessException;
6	import org.springframework.jdbc.core.JdbcTemplate;
7	import org.springframework.jdbc.support.GeneratedKeyHolder;
8	import org.springframework.stereotype.Repository;
9	
10	import java.math.BigDecimal;
11	import java.time.LocalDateTime;
12	import java.util.List;
13	
14	/**
15	 * 泵站启停任务与启停序列仓储。
16	 *
17	 * <p>并发约束由数据库唯一索引保证：
18	 * <ul>
19	 *   <li>{@code uk_zone_time_sequence(pumpdown_id, zone_code, task_time)}：同一分区同一时刻仅一套序列；</li>
20	 *   <li>{@code uk_station_time(station_code, task_time)}：同一泵站同一时刻仅一个启停任务。</li>
21	 * </ul>
22	 */
23	@Repository
24	public class PumpTaskRepository {
25	
26	    private final JdbcTemplate jdbc;
27	
28	    public PumpTaskRepository(JdbcTemplate jdbc) {
29	        this.jdbc = jdbc;
30	    }
31	
32	    /**
33	     * 查找或创建某分区某时刻的联动序列：同分区同时刻并发指令归入同一套序列。
34	     */
35	    public Long findOrCreateSequence(Long pumpdownId, String zoneCode, LocalDateTime taskTime,
36	                                     LocalDateTime now) {
37	        Long existing = findSequenceId(pumpdownId, zoneCode, taskTime);
38	        if (existing != null) {
39	            return existing;
40	        }
41	        try {
42	            GeneratedKeyHolder keyHolder = new GeneratedKeyHolder();
43	            jdbc.update(con -> {
44	                java.sql.PreparedStatement ps = con.prepareStatement(
45	                        """
46	                        INSERT INTO pump_sequence (pumpdown_id, zone_code, task_time, created_at)
47	                        VALUES (?, ?, ?, ?)
48	                        """,
49	                        new String[]{"id"});
50	                ps.setLong(1, pumpdownId);
51	                ps.setString(2, zoneCode);
52	                ps.setObject(3, taskTime);
53	                ps.setObject(4, now);
54	                return ps;
55	            }, keyHolder);
56	            Number key = keyHolder.getKey();
57	            if (key == null) {
58	                throw new IllegalStateException("启停序列自增ID回填失败");
59	            }
60	            return key.longValue();
61	        } catch (DuplicateKeyException e) {
62	            Long concurrent = findSequenceId(pumpdownId, zoneCode, taskTime);
63	            if (concurrent != null) {
64	                return concurrent;
65	            }
66	            throw e;
67	        }
68	    }
69	
70	    private Long findSequenceId(Long pumpdownId, String zoneCode, LocalDateTime taskTime) {
71	        try {
72	            return jdbc.queryForObject(
73	                    "SELECT id FROM pump_sequence WHERE pumpdown_id = ? AND zone_code = ? AND task_time = ?",
74	                    Long.class, pumpdownId, zoneCode, taskTime);
75	        } catch (EmptyResultDataAccessException e) {
76	            return null;
77	        }
78	    }
79	
80	    /**
81	     * 插入单站启停任务。
82	     *
83	     * @return 任务ID；同站同时刻冲突时返回 null（并发指令唯一受理）
84	     */
85	    public Long insertTask(Long sequenceId, Long pumpdownId, String stationCode,
86	                           String action, LocalDateTime taskTime, String reason) {
87	        try {
88	            GeneratedKeyHolder keyHolder = new GeneratedKeyHolder();
89	            jdbc.update(con -> {
90	                java.sql.PreparedStatement ps = con.prepareStatement(
91	                        """
92	                        INSERT INTO pump_task (sequence_id, pumpdown_id, station_code, action,
93	                            task_time, reason) VALUES (?, ?, ?, ?, ?, ?)
94	                        """,
95	                        new String[]{"id"});
96	                ps.setLong(1, sequenceId);
97	                ps.setLong(2, pumpdownId);
98	                ps.setString(3, stationCode);
99	                ps.setString(4, action);
100	                ps.setObject(5, taskTime);
101	                ps.setString(6, reason);
102	                return ps;
103	            }, keyHolder);
104	            Number key = keyHolder.getKey();
105	            if (key == null) {
106	                throw new IllegalStateException("启停任务自增ID回填失败");
107	            }
108	            return key.longValue();
109	        } catch (DuplicateKeyException e) {
110	            return null;
111	        }
112	    }
113	
114	    /** 写入闸门开度到位日志，须与启泵任务同事务提交。 */
115	    public void insertGateLog(Long pumpTaskId, String stationCode, BigDecimal opening,
116	                              LocalDateTime at) {
117	        jdbc.update(
118	                """
119	                INSERT INTO gate_opening_log (pump_task_id, station_code, opening, updated_at)
120	                VALUES (?, ?, ?, ?)
121	                """,
122	                pumpTaskId, stationCode, opening, at);
123	    }
124	
125	    /**
126	     * 查询某泵站在指定时刻之前（不含）最近一次启泵时刻，用于启机间隔校验。
127	     */
128	    public LocalDateTime latestStartTimeBefore(String stationCode, LocalDateTime taskTime) {
129	        List<LocalDateTime> times = jdbc.query(
130	                """
131	                SELECT task_time FROM pump_task
132	                WHERE station_code = ? AND action = 'START' AND task_time < ?
133	                ORDER BY task_time DESC LIMIT 1
134	                """,
135	                (rs, n) -> rs.getObject("task_time", LocalDateTime.class),
136	                stationCode, taskTime);
137	        return times.isEmpty() ? null : times.get(0);
138	    }
139	
140	    /** 最近一条任务记录（动作+时刻），用于判断泵当前运行态。 */
141	    public LastTask latestTask(String stationCode, Long pumpdownId) {
142	        List<LastTask> list = jdbc.query(
143	                """
144	                SELECT action, task_time FROM pump_task
145	                WHERE station_code = ? AND pumpdown_id = ?
146	                ORDER BY task_time DESC, id DESC LIMIT 1
147	                """,
148	                (rs, n) -> new LastTask(rs.getString("action"),
149	                        rs.getObject("task_time", LocalDateTime.class)),
150	                stationCode, pumpdownId);
151	        return list.isEmpty() ? null : list.get(0);
