31	    void anyBusinessFieldChanged_producesDifferentFingerprint() {
32	        String base = Fingerprints.sha256("req-1", "ZN", "ORANGE", t);
33	        assertThat(Fingerprints.sha256("req-1", "ZB", "ORANGE", t)).isNotEqualTo(base);
34	        assertThat(Fingerprints.sha256("req-1", "ZN", "RED", t)).isNotEqualTo(base);
35	        assertThat(Fingerprints.sha256("req-1", "ZN", "ORANGE", t.plusMinutes(1))).isNotEqualTo(base);
36	    }
37	
38	    @Test
39	    void nullAndEmptyAreStable() {
