26	                          PumpdownEventRepository eventRepository) {
27	        this.catalogRepository = catalogRepository;
28	        this.eventRepository = eventRepository;
29	    }
30	
31	    /**
32	     * 处理预警（首次受理）。
33	     * <ul>
34	     *   <li>蓝/黄：不触发预降，返回 NOT_TRIGGERED；</li>
35	     *   <li>橙/红：分区无活动事件时创建 ACTIVE 预降事件；分区已有活动事件返回 409。</li>
36	     * </ul>
37	     */
38	    public WarningResult process(WarningRequest request) {
39	        AlertLevel level = catalogRepository.findAlertLevel(request.alertLevel())
40	                .orElseThrow(() -> ApiException.unprocessable("UNKNOWN_ALERT_LEVEL")
41	                        .raise("未知预警级别: " + request.alertLevel()));
42	        if (!catalogRepository.zoneExists(request.zoneCode())) {
43	            throw ApiException.unprocessable("UNKNOWN_ZONE")
44	                    .raise("未知流域分区: " + request.zoneCode());
45	        }
46	
47	        if (!level.triggerPumpdown()) {
48	            return new WarningResult(null, request.zoneCode(), level.code(), false,
49	                    "NOT_TRIGGERED", null, null, false);
50	        }
51	
52	        if (eventRepository.findActiveByZone(request.zoneCode()).isPresent()) {
53	            throw ApiException.concurrentConflict("ZONE_PUMPDOWN_ACTIVE",
54	                    "分区 " + request.zoneCode() + " 已存在进行中的预降事件，请勿重复启动");
55	        }
56	
57	        BigDecimal targetLevel = resolveZoneTargetLevel(request.zoneCode());
58	        PumpdownEvent event = eventRepository.create(request.requestId(), request.zoneCode(),
59	                level.code(), targetLevel, request.alertTime());
60	        return new WarningResult(event.id(), event.zoneCode(), event.alertLevel(), true,
61	                event.status(), event.startedAt(), event.targetLevel(), false);
62	    }
63	
64	    /** 分区目标水位取区内泵站最严格（最低）目标位。 */
65	    private BigDecimal resolveZoneTargetLevel(String zoneCode) {
66	        List<PumpStation> stations = catalogRepository.stationsOfZone(zoneCode);
67	        return stations.stream()
68	                .map(PumpStation::targetLevel)
69	                .min(BigDecimal::compareTo)
70	                .orElseThrow(() -> ApiException.unprocessable("ZONE_WITHOUT_STATION")
71	                        .raise("分区下无泵站，无法预降: " + zoneCode));
72	    }
73	}
