                config.backwaterThreshold(), config.version(), receivedAt);
        // 固定全部相关站闸门目标：进入强排取站点联动开度，退出强排归零
        List<PumpStation> stations = catalogRepository.stationsOfZone(request.zoneCode());
        for (PumpStation station : stations) {
