        }
        // 退出前提：潮位 < 门槛-0.2；回到回落线及以上即失效
        return tideLevel.compareTo(threshold.subtract(EXIT_HYSTERESIS)) >= 0;
    }

    private void requireZone(String zoneCode) {
        if (!catalogRepository.zoneExists(zoneCode)) {
